def roman(n: int) -> str:
    """Convert 1 <= n <= 3999 to a Roman numeral using subtractive notation (IV, IX, XL, ...)."""
    if not (1 <= n <= 3999):
        raise ValueError("n must be between 1 and 3999 inclusive")

    # Define the values and corresponding numerals in descending order
    values = [
        1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1
    ]
    numerals = [
        'M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'
    ]

    result = ''
    for i in range(len(values)):
        count = n // values[i]
        if count:
            result += numerals[i] * count
            n -= values[i] * count

    return result

