def word_count(s: str) -> dict[str, int]:
    """Count lowercase words split on whitespace."""
    if not s:
        return {}

    words = s.split()
    count = {}

    for word in words:
        lower_word = word.lower()
        count[lower_word] = count.get(lower_word, 0) + 1

    return count
